#include <cstddef>
#include <iostream>

class Buffer {
public:
    explicit Buffer(std::size_t n) : datos_(new int[n]), n_(n) {
        for (std::size_t i = 0; i < n_; ++i) {
            datos_[i] = static_cast<int>(i + 1);
        }
    }

    Buffer(const Buffer& otro) : datos_(new int[otro.n_]), n_(otro.n_) {
        for (std::size_t i = 0; i < n_; ++i) {
            datos_[i] = otro.datos_[i];
        }
    }

    Buffer& operator=(const Buffer& otro) {
        if (this != &otro) {
            int* nuevos = new int[otro.n_];
            for (std::size_t i = 0; i < otro.n_; ++i) {
                nuevos[i] = otro.datos_[i];
            }
            delete[] datos_;
            datos_ = nuevos;
            n_ = otro.n_;
        }
        return *this;
    }

    ~Buffer() { delete[] datos_; }

    int& operator[](std::size_t i) { return datos_[i]; }
    const int& operator[](std::size_t i) const { return datos_[i]; }
    std::size_t size() const { return n_; }

private:
    int* datos_;
    std::size_t n_;
};

int main() {
    Buffer a(3);
    Buffer b = a;      // copia profunda
    b[0] = 99;

    std::cout << a[0] << ' ' << b[0] << '\n';
    std::cout << a.size() << '\n';
    return 0;
}

#include <algorithm>
#include <cstddef>
#include <iostream>
#include <utility>

class Secuencia {
public:
    explicit Secuencia(std::size_t n) : datos_(new double[n]), n_(n) {
        for (std::size_t i = 0; i < n_; ++i) {
            datos_[i] = static_cast<double>(i);
        }
    }

    Secuencia(const Secuencia& otro) : datos_(new double[otro.n_]), n_(otro.n_) {
        std::copy(otro.datos_, otro.datos_ + otro.n_, datos_);
    }

    Secuencia& operator=(const Secuencia& otro) {
        if (this != &otro) {
            Secuencia tmp(otro);
            std::swap(datos_, tmp.datos_);
            std::swap(n_, tmp.n_);
        }
        return *this;
    }

    Secuencia(Secuencia&& otro) noexcept : datos_(otro.datos_), n_(otro.n_) {
        otro.datos_ = nullptr;
        otro.n_ = 0;
    }

    Secuencia& operator=(Secuencia&& otro) noexcept {
        if (this != &otro) {
            delete[] datos_;
            datos_ = otro.datos_;
            n_ = otro.n_;
            otro.datos_ = nullptr;
            otro.n_ = 0;
        }
        return *this;
    }

    ~Secuencia() { delete[] datos_; }

    std::size_t size() const { return n_; }

    friend std::ostream& operator<<(std::ostream& os, const Secuencia& s) {
        os << '[';
        for (std::size_t i = 0; i < s.n_; ++i) {
            if (i > 0) {
                os << ' ';
            }
            os << s.datos_[i];
        }
        return os << ']';
    }

private:
    double* datos_;
    std::size_t n_;
};

int main() {
    Secuencia a(3);
    Secuencia b = a;
    Secuencia c = std::move(a);

    std::cout << b << '\n';
    std::cout << c << '\n';
    std::cout << a.size() << ' ' << c.size() << '\n';
    return 0;
}

