#include <iostream>
#include <numeric>

class Racional {
public:
    Racional(int num, int den) : num_(num), den_(den == 0 ? 1 : den) {
        simplificar();
    }

    Racional operator+(const Racional& otro) const {
        return Racional{num_ * otro.den_ + otro.num_ * den_, den_ * otro.den_};
    }

    bool operator==(const Racional& otro) const {
        return num_ == otro.num_ && den_ == otro.den_;
    }

    friend std::ostream& operator<<(std::ostream& os, const Racional& r) {
        return os << r.num_ << '/' << r.den_;
    }

private:
    void simplificar() {
        const int divisor = std::gcd(num_, den_);
        if (divisor != 0) {
            num_ /= divisor;
            den_ /= divisor;
        }
        if (den_ < 0) {
            num_ = -num_;
            den_ = -den_;
        }
    }

    int num_;
    int den_;
};

int main() {
    const Racional a{1, 2};
    const Racional b{1, 3};

    std::cout << a + b << '\n';
    std::cout << (a == b) << '\n';
    std::cout << (a + b == Racional{5, 6}) << '\n';
    return 0;
}

#include <algorithm>
#include <cstddef>
#include <iostream>
#include <utility>

class Arreglo {
public:
    explicit Arreglo(std::size_t n) : datos_(new int[n]), n_(n) {
        std::fill(datos_, datos_ + n_, 0);
    }

    Arreglo(const Arreglo& otro) : datos_(new int[otro.n_]), n_(otro.n_) {
        std::copy(otro.datos_, otro.datos_ + otro.n_, datos_);
    }

    Arreglo& operator=(const Arreglo& otro) {
        if (this != &otro) {
            Arreglo tmp(otro);
            std::swap(datos_, tmp.datos_);
            std::swap(n_, tmp.n_);
        }
        return *this;
    }

    Arreglo(Arreglo&& otro) noexcept : datos_(otro.datos_), n_(otro.n_) {
        otro.datos_ = nullptr;
        otro.n_ = 0;
    }

    Arreglo& operator=(Arreglo&& otro) noexcept {
        if (this != &otro) {
            delete[] datos_;
            datos_ = otro.datos_;
            n_ = otro.n_;
            otro.datos_ = nullptr;
            otro.n_ = 0;
        }
        return *this;
    }

    ~Arreglo() { delete[] datos_; }

    int& operator[](std::size_t i) { return datos_[i]; }
    int operator[](std::size_t i) const { return datos_[i]; }
    std::size_t size() const { return n_; }

private:
    int* datos_;
    std::size_t n_;
};

int main() {
    Arreglo a(3);
    a[2] = 7;

    Arreglo b = a;
    Arreglo c = std::move(a);

    std::cout << b[2] << ' ' << c[2] << '\n';
    std::cout << a.size() << ' ' << c.size() << '\n';
    return 0;
}

